CREATE OR REPLACE PROCEDURE batch_insert_products(
    product_names TEXT[],
    product_prices NUMERIC[]
)
LANGUAGE plpgsql
AS $$
DECLARE
    i INTEGER;
BEGIN
    FOR i IN 1..array_length(product_names, 1) LOOP
        BEGIN
            SAVEPOINT sp_insert;
            INSERT INTO products (name, price) VALUES (product_names[i], product_prices[i]);
        EXCEPTION
            WHEN OTHERS THEN
                ROLLBACK TO sp_insert;
                RAISE NOTICE 'Failed to insert product %: %', product_names[i], SQLERRM;
        END;
    END LOOP;
END;
$$;
